# Builds the ATS1 reference driver of the test of group 1 (t3g1dump1) against the ATS1-built objects of $SRC (the main tree: `make -C $SRC` first).
# Environment as for t3dump1.sh (ATSHOME, ATSHOMERELOC=ATS-0.2.12, a gcc wrapper accepting K&R C). Run in the build directory DIR/test.
SRC=${ATS1REF:-${SRC:?ATS1REF not set: an ATS1 build of the old src/ is needed (see src/README)}}
OBJS=""
for m in error intinf counter utils global basics stamp symbol filename location errmsg label effect fixity_prec fixity_fxty reader lexbuf lexing lexing_error lexing_print lexing_token syntax syntax_print tokbuf parsing parsing_util parsing_error parsing_kwds parsing_base parsing_e0xp parsing_sort parsing_staexp parsing_p0at parsing_dynexp parsing_decl parsing_toplevel staexp1 staexp1_print dynexp1 dynexp1_print staexp2_sort staexp2 stacst2 staexp2_scst staexp2_svar staexp2_svvar staexp2_dcon staexp2_hole staexp2_ctxt staexp2_error staexp2_solve staexp2_print staexp2_pprint staexp2_szexp staexp2_skexp staexp2_util1 staexp2_util2 staexp2_util3 namespace dynexp2 dynexp2_dcst dynexp2_dmac dynexp2_dvar dynexp2_mapgen dynexp2_print dynexp2_util patcst2 trans3_error dynexp3 dynexp3_print trans3_env trans3_env_svar trans3_env_scst trans3_env_termet trans3_env_effect trans3_env_lamlp trans3_env_print trans3_env_pfman trans3_env_dvar trans3_env_lstate dmacro2 dmacro2_eval0 dmacro2_eval1 dmacro2_print trans3_syncst trans3_util trans3_dynexp_up trans3_p2at trans3_patcon trans3_caseof trans3_dynexp_dn trans3_lvalres trans3_appsym trans3_selab trans3_assgn trans3_deref trans3_xchng trans3_viewat trans3_fldfrat trans3_ptrof trans3_looping trans3_decl; do OBJS="$OBJS $SRC/pats_${m}_dats.o"; done
for m in error intinf counter utils global basics stamp symbol filename location errmsg reader lexbuf lexing label fixity effect syntax parsing tokbuf staexp1 dynexp1 staexp2 staexp2_util staexp2_error stacst2 staexp2_solve namespace trans1_env trans2 trans2_env trans3_env dynexp2 dynexp3 dmacro2 trans3 patcst2 jsonize dyncst2 symmap symenv; do [ -f $SRC/pats_${m}_sats.o ] && OBJS="$OBJS $SRC/pats_${m}_sats.o"; done
atscc -I$SRC -IATS $SRC -D_ATS_NGC -o t3g1dump1 t3g1dump1.dats $OBJS -lats -lgmp
